<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue';import {request,requestBlob} from '@/lib/request';import PrivateUpload from '@/components/PrivateUpload.vue';import {ElMessage,ElMessageBox} from 'element-plus';
interface Attachment {attachmentId:string;fileId:string;fileName:string;orignalName:string;fileType:string;fileSize:number;createTime:string}
const rows=ref<Attachment[]>([]),loading=ref(false),preview=ref(''),open=ref(false),previewKind=ref(''),uploader=ref<InstanceType<typeof PrivateUpload>>();
async function load(){loading.value=true;try{rows.value=(await request<{rows:Attachment[]}>('/api/platform/files',{query:{resource:'personal',pageNum:1,pageSize:100}})).rows}catch(e){ElMessage.error(e instanceof Error?e.message:'加载失败')}finally{loading.value=false}}
async function download(row:Attachment){try{await uploader.value?.download(row.fileId)}catch(e){ElMessage.error(e instanceof Error?e.message:'下载失败')}}
async function show(row:Attachment){if(preview.value)URL.revokeObjectURL(preview.value);preview.value=URL.createObjectURL(await requestBlob('/api/platform/files/'+row.fileId+'/content',{query:{resource:'personal'}}));previewKind.value=row.fileType;open.value=true}
async function remove(row:Attachment){try{await ElMessageBox.confirm('确认删除附件“'+row.fileName+'”？','删除附件',{type:'warning'});await request('/api/platform/files/'+row.fileId,{method:'DELETE',query:{resource:'personal'}});ElMessage.success('附件已删除');await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e instanceof Error?e.message:'删除失败')}}onMounted(load);onBeforeUnmount(()=>{if(preview.value)URL.revokeObjectURL(preview.value)})
</script><template><section class="page"><PageHeader title="个人文件" description="上传、选择、下载和预览本人的附件；文件范围随当前工厂隔离。"/><div class="panel welcome"><PrivateUpload ref="uploader" resource="personal" @uploaded="load"/><el-button @click="load">刷新</el-button><el-table v-loading="loading" :data="rows" empty-text="暂无附件"><el-table-column type="selection" width="50"/><el-table-column prop="orignalName" label="文件名" min-width="200"/><el-table-column prop="fileType" label="类型"/><el-table-column prop="fileSize" label="大小（字节）"/><el-table-column prop="createTime" label="上传时间"/><el-table-column label="操作" width="200"><template #default="{row}"><el-button link type="primary" @click="download(row)">下载</el-button><el-button v-if="/^image\/(png|jpeg|gif|webp)$/.test(row.fileType)" link type="primary" @click="show(row)">预览</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table></div><el-dialog v-model="open" title="附件预览"><img :src="preview" alt="私有附件预览" style="max-width:100%"/></el-dialog></section></template>